color_hlsl:
float2 worldUV=(P.xy/100+4032)/8064;
float4 m=Texture2DSample(Mask,MaskSampler,worldUV);
float4 s=Texture2DSample(Surface,SurfaceSampler,worldUV);
float2 uv=P.xy/260;
float3 grass=Texture2DSample(Grass,GrassSampler,uv).rgb;
float3 broad=Texture2DSample(Grass,GrassSampler,uv*.173+0.27).rgb;
grass=lerp(grass,broad,.24)*float3(.78,1.02,.69);
float3 forest=Texture2DSample(Forest,ForestSampler,uv*.7).rgb;
float3 dirt=Texture2DSample(Mud,MudSampler,uv*.85).rgb;
float3 weights=pow(abs(N),4);weights/=max(dot(weights,1),.0001);
float viewM=distance(P,Camera)/100;
float nearToMid=smoothstep(80,420,viewM);
float midToFar=smoothstep(550,2200,viewM);
float3 rockNear=Texture2DSample(Rock,RockSampler,P.yz/700).rgb*weights.x+Texture2DSample(Rock,RockSampler,P.xz/700).rgb*weights.y+Texture2DSample(Rock,RockSampler,P.xy/700).rgb*weights.z;
float3 rockMid=Texture2DSample(Rock,RockSampler,P.yz/3800).rgb*weights.x+Texture2DSample(Rock,RockSampler,P.xz/3800).rgb*weights.y+Texture2DSample(Rock,RockSampler,P.xy/3800).rgb*weights.z;
float3 rockFar=Texture2DSample(Rock,RockSampler,P.yz/16000).rgb*weights.x+Texture2DSample(Rock,RockSampler,P.xz/16000).rgb*weights.y+Texture2DSample(Rock,RockSampler,P.xy/16000).rgb*weights.z;
float3 rock=lerp(lerp(rockNear,rockMid,nearToMid),rockFar,midToFar);
float macro=.5+.25*sin(P.x/19700+sin(P.y/27300)*1.7)+.25*sin(P.y/11300+P.z/9700);
rock*=lerp(float3(.70,.74,.77),float3(1.05,1.01,.93),macro);
float cliff=saturate((.82-N.z)*4);
float3 base=lerp(grass,forest,m.r*.5);
base=lerp(base,rock,max(cliff,m.a*.45));
float variation=.9+.1*sin(P.x/17300+sin(P.y/11900));
base*=variation;
base=lerp(base,dirt*float3(1.65,1.38,1.04)+float3(.055,.038,.018),s.r*.97);
base=lerp(base,dirt*float3(.66,.61,.48),s.g*.95);
base=lerp(base,Texture2DSample(Cobble,CobbleSampler,P.xy/400).rgb,s.b);

float4 ecology=Texture2DSample(Ecology,EcologySampler,worldUV);
float4 placement=Texture2DSample(Placement,PlacementSampler,worldUV);
float mixWeight=.5+.5*sin(P.x/7300+sin(P.y/9100));
float2 rotated=float2(-uv.y,uv.x)*.413+float2(.19,.37);
float3 turf=lerp(Texture2DSample(Grass,GrassSampler,uv).rgb,Texture2DSample(Grass,GrassSampler,rotated).rgb,.32+.18*mixWeight)*float3(.76,1.01,.69);
float3 litter=lerp(Texture2DSample(Forest,ForestSampler,uv*.83).rgb,Texture2DSample(Forest,ForestSampler,rotated*.71).rgb,.28);
float exposed=1-smoothstep(.50,.76,N.z);
float highRock=smoothstep(102000,134000,P.z)*(.28+.50*macro);
float stoneWeight=max(max(exposed,ecology.g*.40),highRock);
stoneWeight*=1-saturate(s.r+s.g+s.b);
float3 improved=lerp(turf,litter,saturate(ecology.r*1.12));
improved=lerp(improved,rock,stoneWeight);
improved=lerp(improved,Texture2DSample(Mud,MudSampler,uv*.85).rgb*float3(.85,.9,.93),ecology.b*.72);
improved*=lerp(.82,1.08,macro)*(.93+.07*mixWeight);
improved=lerp(improved,dirt*float3(1.65,1.38,1.04)+float3(.055,.038,.018),s.r*.97);
improved=lerp(improved,dirt*float3(.66,.61,.48),s.g*.95);
improved=lerp(improved,Texture2DSample(Cobble,CobbleSampler,P.xy/400).rgb,s.b);
float montaneHabitat=smoothstep(24000,36000,P.z)*(1-smoothstep(110000,128000,P.z))*smoothstep(.50,.75,N.z);
return lerp(base,improved,max(placement.r,montaneHabitat));

normal_hlsl:
float2 worldUV=(P.xy/100+4032)/8064; float2 uv=P.xy/260;
float4 e=Texture2DSample(Ecology,EcologySampler,worldUV);
float4 s=Texture2DSample(Surface,SurfaceSampler,worldUV);
float cover=max(Texture2DSample(Placement,PlacementSampler,worldUV).r,smoothstep(24000,36000,P.z)*(1-smoothstep(110000,128000,P.z))*smoothstep(.50,.75,N.z));
float2 xy=lerp(Texture2DSample(DetailN,DetailNSampler,uv).rg,Texture2DSample(ForestN,ForestNSampler,uv*.83).rg,e.r);
xy=lerp(xy,Texture2DSample(MudN,MudNSampler,uv*.85).rg,e.b);
xy=lerp(xy,Texture2DSample(CobbleN,CobbleNSampler,P.xy/400).rg,s.b)*2-1;
xy*=lerp(.42,.72,s.b);float3 detail=float3(xy,sqrt(saturate(1-dot(xy,xy))));
float3 T=normalize(cross(abs(N.z)>.9?float3(0,1,0):float3(0,0,1),N));float3 B=cross(N,T);
float3 improved=normalize(T*detail.x+B*detail.y+N*detail.z);
float3 w=pow(abs(N),4);w/=max(dot(w,1),.0001);
float2 rnX=Texture2DSample(RockN,RockNSampler,P.yz/700).rg*2-1;
float2 rnY=Texture2DSample(RockN,RockNSampler,P.xz/700).rg*2-1;
float2 rnZ=Texture2DSample(RockN,RockNSampler,P.xy/700).rg*2-1;
float3 relief=float3(0,rnX.x,rnX.y)*w.x+float3(rnY.x,0,rnY.y)*w.y+float3(rnZ.x,rnZ.y,0)*w.z;
float stone=max(1-smoothstep(.50,.76,N.z),e.g*.40)*(1-saturate(s.r+s.g+s.b));
improved=normalize(lerp(improved,normalize(N+relief*.42),stone));
float3 old=lerp(Texture2DSample(DetailN,DetailNSampler,uv).xyz,Texture2DSample(CobbleN,CobbleNSampler,P.xy/400).xyz,s.b)*2-1;
return normalize(lerp(normalize(N+float3(old.xy*.5,0)),improved,cover));
